    "baseline_comparison": "Algorytm referencyjny (baseline) do porównania",
    "planned_visualizations": ["Schemat architektury w TikZ/Mermaid", "Wykresy porównawcze z baseline w matplotlib"]
  },
  "tasks": [
    {
      "task_id": "T1",
