  \node[draw=red!70!black, fill=red!10, rounded corners, minimum width=2.2cm, minimum height=0.9cm, below right=1.8cm and 1.5cm of server, align=center] (c3) {\textbf{Straggler Client} \\ \small Partial Updates};

